	sections = {
		{
			title = "Summary",
			text = [=[Hagar Lightninghoof is a {link:tauren}tauren{/link} of {link:freewind-post}Freewind Post{/link} with a hunger for the unknown. When rumors reached him of a strange egg guarded by the wind serpents, he wanted to see it for himself. He had it brought to Freewind, and he watched it hatch.]=],
		},
		{
			title = "Significance",
			text = [=[What came out of the egg was a young serpent of vengeance, and Hagar understood at once that the old legend of {link:arikara}Arikara{/link} was true. His alarm set the {link:tauren}tauren{/link} of {link:thousand-needles}the Needles{/link} on the serpent's trail.]=],
		},
	},
	chapters = {
