			key = "the-alien-egg",
			title = "The Alien Egg",
			hint = "Bring the strange egg from the serpent dens to Hagar.",
			unlock = {
				{ type = "quest", id = 4821 },
				{ type = "quest", id = 4865 },
			},
			text = [=[The egg lay in a serpent den at the foot of the cliffs, and the serpents guarded it as though it were one of their own. When it was brought to him, Hagar bent close to study it. It broke open before his eyes. He wiped his brow and said that vengeance had come to {link:thousand-needles}Thousand Needles{/link}, and he sent word at once to {link:motega-firemane}Motega Firemane{/link}.]=],
		},
