			title = "Summary",
			text = [=[Rau Cliffrunner is a {link:tauren}tauren{/link} of {link:freewind-post}Freewind Post{/link} who wants to understand the {link:centaurs}centaur{/link}, not only to fight them. With his associate Zangen Stonehoof of {link:thunder-bluff}Thunder Bluff{/link}, he set out to take the Cloven Hoof, a relic the Galak have guarded since the time of their people's making.]=],
