Add({
	kind = "figure",
	id = "motega-firemane",
	title = "Motega Firemane",
	aliases = { "Motega" },
	subtitle = "Keeper of Whitereach Post",
	tier = "B",
	region = "thousand-needles",
	npc = { 10428 },
	allegiance = "Horde · Whitereach Post",
	found = "Whitereach Post",
	pin = { x = 21.5, y = 32.3 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Speak with the tauren who studies the creatures of the Needles at Whitereach Post.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Motega Firemane came to {link:thousand-needles}Thousand Needles{/link} to study the creatures that live there, and he brought the young {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link} with him. He keeps his tents at {link:whitereach-post}Whitereach Post{/link} in the north-west of the canyon. Motega knows the old tales of the {link:tauren}tauren{/link} better than most, and when a serpent of legend came back to the Needles, it was to him that the tauren turned.]=],
		},
		{
			title = "Significance",
			text = [=[Motega is the bridge between {link:thousand-needles}the Needles{/link} and the Elder Crone. It was he who sent word to {link:magatha-grimtotem}Magatha Grimtotem{/link} of the serpent {link:arikara}Arikara{/link}, and he who received the powder that would call it from the sacred fire. He was also the first to find her warning strange.]=],
		},
		{
			title = "Deeds",
			text = [=[• He studies the creatures of {link:thousand-needles}Thousand Needles{/link} from {link:whitereach-post}Whitereach Post{/link}.
• He watches over {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link}, whose father was reluctant to let the boy come.
• He knows the legend of {link:arikara}Arikara{/link}, the serpent born to avenge heinous acts.
• He sent for {link:magatha-grimtotem}Magatha{/link}'s help to kindle the dormant sacred fire of the {link:darkcloud-pinnacle}Darkcloud Pinnacle{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Little is written of Motega's life before {link:whitereach-post}Whitereach Post{/link}. Who {link:pao-ka-swiftmountain}Pao'ka{/link}'s father is, and why he trusted the boy to Motega, is not recorded.]=],
		},
	},
	chapters = {
		{
			key = "the-lost-boy",
			title = "The Lost Boy",
			hint = "Bring Pao'ka home from Highperch.",
			unlock = {
				{ type = "quest", id = 4770 },
			},
			text = [=[{link:pao-ka-swiftmountain}Pao'ka{/link} went alone into {link:highperch}Highperch{/link} to study the wyverns and did not come back. When the boy was at last brought home, Motega was furious. He said that if he had known, he would have chained him to a totem. Beneath the anger he was grateful, and he rewarded those who had helped.]=],
		},
		{
			key = "the-legend-of-arikara",
			title = "The Legend of Arikara",
			hint = "Answer Hagar Lightninghoof's warning.",
			unlock = {
				{ type = "quest", id = 4865 },
				{ type = "quest", id = 5062 },
			},
			text = [=[Motega had heard of {link:arikara}Arikara{/link} all his life and never believed he would see her. Now the legend was true. To hunt the serpent, the sacred fire of life on the {link:darkcloud-pinnacle}Darkcloud Pinnacle{/link} had to be lit, and only a powerful shaman could enchant the rare Incendia agave that would light it. Motega sent the gathered agave to {link:magatha-grimtotem}Magatha Grimtotem{/link} in {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
		{
			key = "a-troubling-answer",
			title = "A Troubling Answer",
			hint = "Slay Arikara and return to Whitereach Post.",
			unlock = {
				{ type = "quest", id = 5088 },
			},
			text = [=[The Elder Crone had warned that {link:arikara}Arikara{/link} might be stalking {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, angered because too much of the old lore of the {link:tauren}tauren{/link} had changed. When the serpent was slain, Motega shook his head. It made no sense to him that Arikara would hunt the High Chieftain. Yet he would not say that {link:magatha-grimtotem}Magatha{/link} was wrong. She was, he said, the most powerful of them.]=],
		},
	},
	mentions = {
		{
			text = "Homeward Bound",
			unlock = {
				{ type = "quest", id = 4770 },
			},
		},
		{
			text = "Serpent Wild",
			unlock = {
				{ type = "quest", id = 4865 },
			},
		},
		{
			text = "Sacred Fire",
			unlock = {
				{ type = "quest", id = 5062 },
			},
		},
		{
			text = "{link:arikara}Arikara{/link}",
			unlock = {
				{ type = "quest", id = 5088 },
			},
		},
	},
	bonds = {
		{ id = "pao-ka-swiftmountain", name = "Pao'ka Swiftmountain", note = "the boy in his care" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "brought him the news" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "enchanted the powder" },
		{ id = "arikara", name = "Arikara", note = "the serpent of legend" },
		{ id = "kanati-greycloud", name = "Kanati Greycloud", note = "shares Whitereach Post" },
