			text = [=[Dorn Plainstalker dwells alone on a height above {link:thousand-needles}the Needles{/link}, far from the bustle of {link:freewind-post}Freewind Post{/link}. He counts it his duty to prepare the young of every tribe for the dangers they will meet after they leave the safety of home. He tests them in three things: the spirit, the body and the mind. Those who pass return stronger. Those who fail, he says, learn how vast the world truly is.]=],
		},
		{
			title = "Significance",
			text = [=[Dorn is a teacher of the old kind. He does not care which tribe a warrior comes from, only whether that warrior is ready. His trials bind together several of the {link:horde}Horde{/link}'s wise ones across {link:kalimdor}Kalimdor{/link} and beyond.]=],
		},
		{
			title = "Deeds",
			text = [=[• He tests the faith, endurance, strength and lore of the young.
• He sends them against the {link:harpies}harpy{/link} matriarch of {link:roguefeather-den}Roguefeather Den{/link} and the elemental {link:rok-alim-the-pounder}Rok'Alim{/link}.
• He sends them on to the shaman {link:braug-dimspirit}Braug Dimspirit{/link} in {link:stonetalon-mountains}Stonetalon{/link} for the test of lore.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Little is written of Dorn's life or of how long he has kept his height. His tribe is not named.]=],
		},
	},
	chapters = {
		{
			key = "the-leap-of-faith",
			title = "The Leap of Faith",
			hint = "Prove your faith on Dorn's height.",
			unlock = {
				{ type = "quest", id = 1149 },
			},
			text = [=[Dorn's first test is the strangest. He asks the young to step from the planks of his height into empty air, with no promise that they will live. Faith, he teaches, matters more than many realize. It is not always important what one believes, but that one believes in something.]=],
		},
		{
			key = "body-and-strength",
			title = "Body and Strength",
			hint = "Pass the tests of endurance and strength.",
			unlock = {
				{ type = "quest", id = 1150 },
				{ type = "quest", id = 1151 },
			},
			text = [=[For the body, Dorn sends the young into {link:roguefeather-den}Roguefeather Den{/link} to spoil the harpies' stores and face {link:grenka-bloodscreech}Grenka Bloodscreech{/link} when she comes in her fury. For strength, he sends them against {link:rok-alim-the-pounder}Rok'Alim{/link}, an elemental who has lingered in {link:thousand-needles}the Needles{/link} since the age of the Old Gods.]=],
		},
		{
			key = "the-final-passage",
			title = "The Final Passage",
			hint = "Complete the test of lore and return to Dorn.",
			unlock = {
				{ type = "quest", id = 1394 },
			},
			text = [=[The test of lore is not his to give. It passes through {link:braug-dimspirit}Braug Dimspirit{/link} in {link:stonetalon-mountains}Stonetalon{/link} and beyond, to scholars far from {link:thousand-needles}the Needles{/link}. When at last the young return to Dorn, he looks at them as though many moons have passed since their first leap, and he tells them their mind, body and spirit are strong.]=],
