			unlock = {
				{ type = "quest", id = 1183 },
			},
			text = [=[{link:gazlowe}Gazlowe{/link} had promised a new fuel regulator, and it never came. The trail ran from {link:ratchet}Ratchet{/link} to the wharves of {link:booty-bay}Booty Bay{/link} and to {link:baron-revilgaz}Baron Revilgaz{/link}, who admitted his men had failed to find the blueprints. The plans lay in the house of a {link:venture-company}Venture Company{/link} foreman in {link:stranglethorn-vale}Stranglethorn Vale{/link}, who had fitted the new regulator to his shredders. When the blueprints reached Pozzik at last, they were only drawings. He was pleased all the same, for now he could improve the design from the ground up.]=],
