		},
		{
			title = "Significance",
			text = [=[Kravel is the underside of {link:mirage-raceway}the Mirage Raceway{/link}. Through him the rivalry of goblins and gnomes becomes a trade in secrets, bribes and drugged ale, and his reach runs from {link:ratchet}Ratchet{/link} to {link:booty-bay}Booty Bay{/link}.]=],
